export default function f({ items, previous, owner, repo, basePath }) {
  if (!owner || !repo || owner.includes("YOUR_") || repo.includes("YOUR_"))
    throw Error("Configure GitHub repository");
  const s = previous ?? { index: 0 },
    item = items[s.index++];
  if (!item) return { state: s, more: false, id: "-", content: "", path: "-", endpoint: "/unused" };
  let path = [basePath.replace(/^\/+|\/+$/g, ""), item.domain, item.id + ".html"]
    .filter(Boolean)
    .join("/");
  if (path.split("/").some((x) => !x || x === "." || x === ".." || !/^[-\w.]+$/.test(x)))
    throw Error("Invalid backup path");
  return {
    state: s,
    more: true,
    id: item.id,
    content: item.content,
    path,
    endpoint:
      "/repos/" +
      encodeURIComponent(owner) +
      "/" +
      encodeURIComponent(repo) +
      "/contents/" +
      path.split("/").map(encodeURIComponent).join("/"),
  };
}

