import { Buffer } from "node:buffer";
export default async function f(
  { status, body, path, owner, repo, content, ack, resolution },
  ctx,
) {
  if (![200, 404].includes(status)) throw Error("GitHub read failed");
  let sha = null,
    same = false;
  if (status === 200) {
    if (
      body?.type !== "file" ||
      body.path !== path ||
      !body.sha ||
      body.encoding !== "base64" ||
      typeof body.content !== "string"
    )
      throw Error("Invalid GitHub file");
    sha = body.sha;
    same = Buffer.from(body.content.replace(/\s/g, ""), "base64").toString("utf8") === content;
  }
  const key = "squarespace-backup:" + owner + "/" + repo + "/" + path,
    s = await ctx.state.get(key);
  if (s) {
    if (ack !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + key);
    if (resolution === "confirmed") {
      if (!same) throw Error("File does not match");
      await ctx.state.set(key, null);
      return { write: false, key, sha: null };
    }
    if (s.sha !== sha || s.status !== status) throw Error("Destination changed");
    await ctx.state.set(key, null);
  }
  if (same) return { write: false, key, sha: null };
  await ctx.state.set(key, { status, sha });
  return { write: true, key, sha };
}

